    const geo = new THREE.BoxGeometry(0.7, h, 0.7);
    const mat = barMat(barPalette[i%2], i===5 ? 0xc9a24d : 0x000000);
    const bar = new THREE.Mesh(geo, mat);
    bar.position.set((i - (barCount-1)/2)*spacing, h/2 - 1.6, 0);
    monument.add(bar);
