  const scatterMat = new THREE.MeshStandardMaterial({ color:0xe6cd8d, metalness:0.85, roughness:0.25, emissive:0x33260d, emissiveIntensity:0.4 });
  const cashMat = new THREE.MeshStandardMaterial({ color:0xf3efe4, metalness:0.05, roughness:0.7 });
