    mesh.rotation.y = Math.random()*Math.PI*2;
    mesh.rotation.x = (Math.random()-0.5)*0.3;
    mesh.userData.bobSpeed = 0.3 + Math.random()*0.5;
    mesh.userData.bobOffset = Math.random()*Math.PI*2;
